/*
 * Copyright (c) 2023 OpenHands
 * SPDX-License-Identifier: Apache-2.0
 */

/ {
	/* Add a flash device with compatible "soc-nv-flash" for mapped partitions */
	sim_flash: flash@10000000 { /* Unique address */
		compatible = "soc-nv-flash";
		reg = <0x10000000 0x100000>; /* 1MB flash */
		status = "okay";
		#address-cells = <1>;
		#size-cells = <1>;
		erase-block-size = <0x10000>; /* Required for soc-nv-flash */
		write-block-size = <1>; /* Required for soc-nv-flash */

		partitions {
			compatible = "fixed-partitions";
			ranges;
			#address-cells = <1>;			
			#size-cells = <1>;

			sim_storage_partition: partition@0 {
				compatible = "zephyr,mapped-partition";
				label = "sim_storage";
				reg = <0x00000000 0x100000>; /* Full 1MB for storage */
			};
		};
	};
};

